package dev.zomboid.skills;import java.util.*;public class ListChecks {public static void main(String[] args){List<String> original=List.of("fitness","scavenging");List<String> active=MechanicalList.include(original);if(!active.equals(List.of("fitness","scavenging","mechanics")))throw new AssertionError("mechanics not appended");if(original.contains("mechanics"))throw new AssertionError("original mutated");if(MechanicalList.include(active).size()!=3)throw new AssertionError("duplicate skill");try{active.add("invalid");throw new AssertionError("list must be immutable");}catch(UnsupportedOperationException expected){}System.out.println("Mechanical skill list checks: 4");}}
